import java.util.Scanner;
class InsufficientFundException extends Exception { InsufficientFundException(){super("Insufficient balance. Minimum balance is 500.");} }
class SavingAccount { private int acno;private String name;private double balance;SavingAccount(int a,String n,double b){acno=a;name=n;balance=b;}void deposit(double x){if(x>0)balance+=x;}void withdraw(double x)throws InsufficientFundException{if(x<=0||balance-x<500)throw new InsufficientFundException();balance-=x;}void viewBalance(){System.out.println("Account: "+acno+" Name: "+name+" Balance: "+balance);} }
public class SavingAccountDemo { public static void main(String[] a){Scanner s=new Scanner(System.in);System.out.print("Account no, name, opening balance: ");int no=s.nextInt();s.nextLine();String name=s.nextLine();double bal=s.nextDouble();if(bal<500)bal=500;SavingAccount x=new SavingAccount(no,name,bal);x.viewBalance();System.out.print("Deposit: ");x.deposit(s.nextDouble());System.out.print("Withdraw: ");try{x.withdraw(s.nextDouble());}catch(InsufficientFundException e){System.out.println(e.getMessage());}x.viewBalance();s.close();} }
